const EYE_L = "M63.9 45.1L65.4 45.1L66.8 45.9L68 47.6L68 49.2L66.9 50.9L65.2 51.8L63.8 51.8L62.4 51L61.1 49.2L61.1 48L62 46.4Z";
const EYE_R = "M91.9 45.1L93.2 45.1L94.5 45.8L96 47.6L96 49.1L95.8 49.8L94.8 51L93.4 51.8L91.6 51.8L90 50.8L89 49.1L89.1 47.6L89.9 46.4Z";
const MOUTH = "M67.5 57.6L68.6 56.1L70 55.9L70.8 56.1L74.1 58.8L77.1 59.5L79.2 59.5L82.1 58.6L84.6 56.4L85.2 56L86.1 55.9L86.6 56L88 57.4L88.1 58.6L87.9 59.5L86.9 60.8L84.1 62.9L81.2 63.9L77.2 64.1L74.4 63.8L71.9 62.9L70.2 61.9L67.9 59.6L67.5 58.5Z";

(() => {
  const brand = document.querySelector(".brand");
  if (!brand) return;

  const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;

  brand.querySelectorAll(".character").forEach((img) => img.remove());
  brand.insertAdjacentHTML(
    "afterbegin",
    `<svg class="character ch" viewBox="0 0 160 152" aria-hidden="true">
      <g class="ch-squish">
        <g class="ch-breathe">
          <path class="ch-body" fill-rule="evenodd" d="${BODY}"/>
          <g class="ch-eyes">
            <path class="ch-eye" data-side="l" d="${EYE_L}"/>
            <path class="ch-eye" data-side="r" d="${EYE_R}"/>
          </g>
          <path class="ch-mouth" d="${MOUTH}"/>
          <path class="ch-alt"/>
          <path class="ch-alt-fill"/>
        </g>
      </g>
      <g class="ch-zzz"><text x="122" y="26">z</text><text x="134" y="14">z</text><text x="146" y="2">z</text></g>
    </svg>`,
  );

  const svg = brand.querySelector(".ch");
  const squish = svg.querySelector(".ch-squish");
  const breathe = svg.querySelector(".ch-breathe");
  const eyes = svg.querySelector(".ch-eyes");
  const eyeL = svg.querySelector('[data-side="l"]');
  const eyeR = svg.querySelector('[data-side="r"]');
  const mouth = svg.querySelector(".ch-mouth");
  const alt = svg.querySelector(".ch-alt");
  const altFill = svg.querySelector(".ch-alt-fill");
  const zs = [...svg.querySelectorAll(".ch-zzz text")];

  // null keeps the traced eye/mouth, a string is drawn in its place
  const closed = (x) => `M${x - 3.2} 48Q${x} 51.5 ${x + 3.2} 48`;
  const caret = (x) => `M${x - 3} 50.5L${x} 46.5L${x + 3} 50.5`;
  const faces = {
    normal: {},
    happy: { l: caret(64.6), r: caret(92.6), fill: "M68.5 56.5Q78 71 87.5 56.5Z" },
    surprised: { fill: "M78 55.5a4 4.6 0 1 0 0.01 0Z" },
    wink: { l: closed(64.6) },
    sleep: { l: closed(64.6), r: closed(92.6), stroke: "M74 59.5Q78 62 82 59.5" },
  };
  let face = "normal";

  function setFace(name) {
    face = name;
    const f = faces[name];
    const newMouth = f.fill || f.stroke;
    eyeL.style.display = f.l ? "none" : "";
    eyeR.style.display = f.r ? "none" : "";
    mouth.style.display = newMouth ? "none" : "";
    alt.setAttribute("d", (f.l || "") + (f.r || "") + (f.stroke || ""));
    altFill.setAttribute("d", f.fill || "");
  }
  setFace("normal");

  // eyes follow the cursor, eased toward the target each frame
  const eye = { x: 0, y: 0, tx: 0, ty: 0 };
  addEventListener("pointermove", (e) => {
    const box = svg.getBoundingClientRect();
    const dx = e.clientX - (box.left + box.width / 2);
    const dy = e.clientY - (box.top + box.height * 0.33);
    const dist = Math.hypot(dx, dy) || 1;
    const reach = Math.min(dist / 120, 1) * 4;
    eye.tx = (dx / dist) * reach;
    eye.ty = (dy / dist) * reach;
  });

  (function tick() {
    const target = face === "sleep" ? { x: 0, y: 0 } : { x: eye.tx, y: eye.ty };
    eye.x += (target.x - eye.x) * 0.15;
    eye.y += (target.y - eye.y) * 0.15;
    eyes.setAttribute("transform", `translate(${eye.x.toFixed(2)} ${eye.y.toFixed(2)})`);
    requestAnimationFrame(tick);
  })();

  function blink() {
    if (face !== "sleep") {
      [eyeL, eyeR].forEach((el) =>
        el.animate(
          [{ transform: "scaleY(1)" }, { transform: "scaleY(0.1)" }, { transform: "scaleY(1)" }],
          { duration: 160, easing: "ease-in-out" },
        ),
      );
    }
    setTimeout(blink, 2000 + Math.random() * 4000);
  }
  setTimeout(blink, 1500);

  function hop(frames, duration) {
    if (reduceMotion) return;
    squish.animate(frames, { duration, easing: "cubic-bezier(.3,.7,.4,1)" });
  }

  let breathing;
  function breathe_(speed, depth) {
    if (reduceMotion) return;
    breathing?.cancel();
    breathing = breathe.animate(
      [
        { transform: "scale(1, 1)" },
        { transform: `scale(${1 - depth / 3}, ${1 + depth})` },
      ],
      { duration: speed, direction: "alternate", iterations: Infinity, easing: "ease-in-out" },
    );
  }
  breathe_(1800, 0.025);

  let snoring = [];
  let idleTimer;

  function sleep() {
    setFace("sleep");
    breathe_(2600, 0.045);
    if (reduceMotion) return;
    snoring = zs.map((z, i) =>
      z.animate(
        [
          { opacity: 0, transform: "translate(0, 8px) scale(0.6)" },
          { opacity: 1, offset: 0.3 },
          { opacity: 0, transform: "translate(6px, -10px) scale(1.1)" },
        ],
        { duration: 2400, delay: i * 600, iterations: Infinity, easing: "ease-out" },
      ),
    );
  }

  function wake() {
    if (face === "sleep") {
      snoring.forEach((a) => a.cancel());
      breathe_(1800, 0.025);
      react("surprised", 700);
      hop([{ transform: "translateY(0)" }, { transform: "translateY(-10px)" }, { transform: "translateY(0)" }], 400);
    }
    clearTimeout(idleTimer);
    idleTimer = setTimeout(sleep, 20000);
  }
  ["pointermove", "pointerdown", "keydown", "scroll", "touchstart"].forEach((ev) =>
    addEventListener(ev, wake, { passive: true }),
  );
  wake();

  let resetTimer;
  function react(name, ms) {
    setFace(name);
    clearTimeout(resetTimer);
    resetTimer = setTimeout(() => setFace("normal"), ms);
  }

  const reactions = ["happy", "surprised", "wink"];
  let clicks = 0;
  const home = (p) => p.replace(/index\.html$/, "");

  brand.addEventListener("click", (e) => {
    // already home: play instead of reloading
    if (home(new URL(brand.href).pathname) === home(location.pathname)) e.preventDefault();
    react(reactions[clicks++ % reactions.length], 1200);
    hop(
      [
        { transform: "scale(1, 1)" },
        { transform: "scale(1.15, 0.8)" },
        { transform: "scale(0.92, 1.12) translateY(-6px)" },
        { transform: "scale(1.03, 0.97)" },
        { transform: "scale(1, 1)" },
      ],
      550,
    );
  });
})();
